.logo {
    font-size: var(--font-size-2xl);
    font-weight: 700;
    letter-spacing: -1px;
    background: linear-gradient(135deg, var(--color-accent), #a78bfa);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.nav-primary ul {
    list-style: none;
    display: flex;
    gap: var(--spacing-xl);
}

.nav-primary a {
    color: var(--color-text-secondary);
    text-decoration: none;
    transition: color var(--transition-fast);
    position: relative;
}

.nav-primary a:hover,
.nav-primary a:focus {
    color: var(--color-accent);
    outline: none;
}

.nav-primary a::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--color-accent);
    transition: width var(--transition-fast);
}

.nav-primary a:hover::after,
.nav-primary a:focus::after {
    width: 100%;
}

.cart-button {
    background: none;
    border: none;
    color: var(--color-text-secondary);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-size: var(--font-size-base);
    transition: color var(--transition-fast);
    position: relative;
}

.cart-button:hover,
.cart-button:focus {
    color: var(--color-accent);
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.cart-count {
    background: var(--color-accent);
    color: white;
    border-radius: 50%;
    width: 20px;
    height: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 600;
}

/* ============================================
   Main Content & Sections
   ============================================ */

main {
    min-height: calc(100vh - 60px);
}

.section {
    padding: var(--spacing-2xl) 0;
    border-bottom: 1px solid var(--color-dark-border);
}

.section h2 {
    font-size: var(--font-size-3xl);
    margin-bottom: var(--spacing-md);
    line-height: 1.2;
}

.section-subtitle {
    color: var(--color-text-secondary);
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-2xl);
}

/* ============================================
   Hero Section
   ============================================ */

.hero {
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.1), rgba(167, 139, 250, 0.1));
    border-bottom: 1px solid var(--color-dark-border);
    min-height: 60vh;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
}

.hero-content h2 {
    font-size: 3.5rem;
    margin-bottom: var(--spacing-md);
    background: linear-gradient(135deg, var(--color-accent), #a78bfa);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.hero-content p {
    font-size: var(--font-size-xl);
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-xl);
}

/* ============================================
   Featured Products
   ============================================ */

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: var(--spacing-xl);
    list-style: none;
}

.product-card {
    background: var(--color-dark-surface);
    border: 1px solid var(--color-dark-border);
    border-radius: 8px;
    overflow: hidden;
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    border-color: var(--color-accent);
    box-shadow: 0 0 30px rgba(99, 102, 241, 0.2);
    transform: translateY(-4px);
}

.product-card:focus-within {
    outline: 2px solid var(--color-accent);
    outline-offset: 0;
}

.product-image {
    width: 100%;
    height: 200px;
    object-fit: cover;
    transition: transform var(--transition-base);
}

.product-card:hover .product-image {
    transform: scale(1.05);
}

.product-info {
    padding: var(--spacing-lg);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.product-info h3 {
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-xs);
    line-height: 1.3;
}

.product-category {
    color: var(--color-text-secondary);
    font-size: var(--font-size-sm);
    margin-bottom: var(--spacing-md);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.product-rating {
    margin-bottom: var(--spacing-md);
}

.stars {
    color: #fbbf24;
    font-size: var(--font-size-sm);
    letter-spacing: 2px;
}

.product-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: auto;
}

.price {
    font-size: var(--font-size-xl);
    font-weight: 600;
    color: var(--color-accent);
}

/* ============================================
   Buttons
   ============================================ */

.btn-primary,
.btn-secondary,
.btn-add-cart {
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: var(--font-size-base);
    font-weight: 600;
    transition: all var(--transition-fast);
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.btn-primary {
    background: var(--color-accent);
    color: white;
    padding: var(--spacing-sm) var(--spacing-lg);
}

.btn-primary:hover,
.btn-primary:focus {
    background: var(--color-accent-hover);
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.btn-secondary {
    background: transparent;
    color: var(--color-accent);
    border: 1px solid var(--color-accent);
    padding: var(--spacing-sm) var(--spacing-lg);
}

.btn-secondary:hover,
.btn-secondary:focus {
    background: rgba(99, 102, 241, 0.1);
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.btn-add-cart {
    width: 36px;
    height: 36px;
    background: var(--color-accent);
    color: white;
    border-radius: 50%;
    font-size: var(--font-size-lg);
    line-height: 1;
}

.btn-add-cart:hover,
.btn-add-cart:focus {
    background: var(--color-accent-hover);
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* ============================================
   Deals Section
   ============================================ */

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-xl);
}

.deal-card {
    background: var(--color-dark-surface);
    border: 1px solid var(--color-dark-border);
    border-radius: 8px;
    overflow: hidden;
    transition: all var(--transition-base);
    position: relative;
}

.deal-card:hover {
    border-color: var(--color-accent);
    box-shadow: 0 0 30px rgba(99, 102, 241, 0.2);
    transform: translateY(-4px);
}

.deal-badge {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background: var(--color-accent);
    color: white;
    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: 4px;
    font-size: var(--font-size-sm);
    font-weight: 600;
    z-index: 10;
}

.deal-preview {
    width: 100%;
    height: 200px;
}

.deal-content {
    padding: var(--spacing-lg);
}

.deal-content h3 {
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-sm);
}

.deal-content p {
    color: var(--color-text-secondary);
    font-size: var(--font-size-sm);
    margin-bottom: var(--spacing-md);
}

.price-comparison {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-lg);
}

.price-original {
    color: var(--color-text-secondary);
    text-decoration: line-through;
    font-size: var(--font-size-sm);
}

.price-sale {
    font-size: var(--font-size-xl);
    font-weight: 700;
    color: var(--color-success);
}

/* ============================================
   Editorial Section
   ============================================ */

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-xl);
    list-style: none;
}

.editorial-card {
    background: var(--color-dark-surface);
    border: 1px solid var(--color-dark-border);
    border-radius: 8px;
    overflow: hidden;
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    border-color: var(--color-accent);
    box-shadow: 0 0 30px rgba(99, 102, 241, 0.2);
    transform: translateY(-4px);
}

.editorial-image {
    width: 100%;
    height: 240px;
    object-fit: cover;
}

.editorial-content {
    padding: var(--spacing-lg);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.editorial-tag {
    display: inline-block;
    background: rgba(99, 102, 241, 0.1);
    color: var(--color-accent);
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: 4px;
    font-size: var(--font-size-sm);
    font-weight: 600;
    margin-bottom: var(--spacing-md);
    width: fit-content;
}

.editorial-card h3 {
    font-size: var(--font-size-xl);
    margin-bottom: var(--spacing-md);
    line-height: 1.3;
}

.editorial-card p {
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-lg);
    flex: 1;
}

.read-more {
    color: var(--color-accent);
    text-decoration: none;
    font-weight: 600;
    transition: all var(--transition-fast);
}

.read-more:hover,
.read-more:focus {
    color: var(--color-accent-hover);
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* ============================================
   Newsletter Section
   ============================================ */

.newsletter-section {
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.15), rgba(167, 139, 250, 0.15));
    border-bottom: 1px solid var(--color-dark-border);
    padding: var(--spacing-2xl) 0;
    text-align: center;
}

.newsletter-section h2 {
    margin-bottom: var(--spacing-md);
}

.newsletter-section p {
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-xl);
    font-size: var(--font-size-lg);
}

.newsletter-form {
    max-width: 500px;
    margin: 0 auto;
    display: flex;
    gap: var(--spacing-md);
    flex-wrap: wrap;
    justify-content: center;
}

.newsletter-form input {
    flex: 1;
    min-width: 250px;
    background: var(--color-dark-surface);
    border: 1px solid var(--color-dark-border);
    color: var(--color-text-primary);
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: 6px;
    font-size: var(--font-size-base);
    transition: all var(--transition-fast);
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--color-accent);
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1);
}

.newsletter-form input::placeholder {
    color: var(--color-text-secondary);
}

.error-message {
    color: var(--color-error);
    font-size: var(--font-size-sm);
    width: 100%;
    text-align: left;
    display: none;
}

.error-message.show {
    display: block;
}

/* ============================================
   Footer
   ============================================ */

.footer {
    background: var(--color-dark-surface);
    border-top: 1px solid var(--color-dark-border);
    padding: var(--spacing-2xl) 0 var(--spacing-lg);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-2xl);
}

.footer-column h4 {
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-base);
}

.footer-column ul {
    list-style: none;
}

.footer-column a {
    color: var(--color-text-secondary);
    text-decoration: none;
    font-size: var(--font-size-sm);
    transition: color var(--transition-fast);
    display: block;
    margin-bottom: var(--spacing-sm);
}

.footer-column a:hover,
.footer-column a:focus {
    color: var(--color-accent);
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.footer-bottom {
    border-top: 1px solid var(--color-dark-border);
    padding-top: var(--spacing-lg);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--spacing-md);
}

.footer-bottom p {
    font-size: var(--font-size-sm);
    color: var(--color-text-secondary);
}

.footer-bottom ul {
    list-style: none;
    display: flex;
    gap: var(--spacing-lg);
}

/* ============================================
   Notification
   ============================================ */

.notification {
    position: fixed;
    bottom: var(--spacing-lg);
    right: var(--spacing-lg);
    background: var(--color-success);
    color: white;
    padding: var(--spacing-md) var(--spacing-lg);
    border-radius: 6px;
    box-shadow: var(--shadow-lg);
    opacity: 0;
    transform: translateY(20px);
    pointer-events: none;
    transition: all var(--transition-base);
    z-index: 1000;
}

.notification.show {
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
}

/* ============================================
   Responsive Design
   ============================================ */

@media (max-width: 768px) {
    .header-content {
        padding: var(--spacing-md);
    }

    .nav-primary ul {
        gap: var(--spacing-md);
        font-size: var(--font-size-sm);
    }

    .logo {
        font-size: var(--font-size-xl);
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .section h2 {
        font-size: var(--font-size-2xl);
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: var(--spacing-md);
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input {
        min-width: 100%;
    }

    .footer-bottom {
        justify-content: center;
        flex-direction: column;
    }
}

@media (max-width: 480px) {
    :root {
        --spacing-lg: 16px;
        --spacing-xl: 20px;
        --spacing-2xl: 32px;
    }

    .container {
        padding: 0 var(--spacing-md);
    }

    .hero {
        min-height: 40vh;
    }

    .hero-content h2 {
        font-size: 1.75rem;
    }

    .nav-primary ul {
        flex-direction: column;
        gap: var(--spacing-md);
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }
}

/* ============================================
   Forced Colors Mode (Accessibility)
   ============================================ */

@media (forced-colors: active) {
    .product-card,
    .deal-card,
    .editorial-card,
    .btn-primary,
    .btn-secondary {
        border: 2px solid CanvasText;
    }

    .btn-primary {
        background: ButtonText;
        color: Canvas;
    }

    .btn-add-cart {
        border: 2px solid CanvasText;
    }

    .product-image,
    .deal-preview,
    .editorial-image {
        forced-color-adjust: none;
        border: 1px solid CanvasText;
    }
}

/* ============================================
   Prefers Reduced Motion
   ============================================ */

@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

