        --spacing-xl: 20px;
        --spacing-2xl: 32px;
    }

    .container {
        padding: 0 var(--spacing-md);
    }

    .hero {
        min-height: 40vh;
    }

    .hero-content h2 {
        font-size: 1.75rem;
    }

    .nav-primary ul {
        flex-direction: column;
        gap: var(--spacing-md);
    }

    .footer-grid {
        grid-template-columns: 1fr;
