   ============================================ */

@media (forced-colors: active) {
    .product-card,
    .deal-card,
    .editorial-card,
    .btn-primary,
    .btn-secondary {
        border: 2px solid CanvasText;
    }

    .btn-primary {
        background: ButtonText;
        color: Canvas;
    }

    .btn-add-cart {
        border: 2px solid CanvasText;
    }

    .product-image,
    .deal-preview,
    .editorial-image {
        forced-color-adjust: none;
        border: 1px solid CanvasText;
    }
}

/* ============================================
