/* ============================================
   Newsletter Subscription
   ============================================ */

class NewsletterForm {
    constructor() {
        this.form = document.querySelector('.newsletter-form');
        this.emailInput = document.getElementById('email-input');
        this.errorMessage = document.getElementById('email-error');

        if (this.form) {
            this.form.addEventListener('submit', (e) => this.handleSubmit(e));
            this.emailInput.addEventListener('input', () => this.clearError());
        }
    }

    handleSubmit(event) {
        event.preventDefault();

        const email = this.emailInput.value.trim();

        if (!this.validateEmail(email)) {
            this.showError('Please enter a valid email address');
            return;
        }

        // Simulate API call
        const originalText = event.target.querySelector('button').textContent;
        const button = event.target.querySelector('button');
        button.textContent = 'Subscribing...';
        button.disabled = true;

        setTimeout(() => {
            this.saveSubscription(email);
            button.textContent = originalText;
            button.disabled = false;
            this.emailInput.value = '';
            this.showSuccess('Successfully subscribed!');
        }, 1000);
    }

    validateEmail(email) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }

    showError(message) {
        this.errorMessage.textContent = message;
        this.errorMessage.classList.add('show');
        this.emailInput.setAttribute('aria-invalid', 'true');
    }

    clearError() {
        this.errorMessage.classList.remove('show');
        this.emailInput.setAttribute('aria-invalid', 'false');
    }

    showSuccess(message) {
        this.clearError();
        const notification = document.getElementById('notification');
        if (notification) {
            notification.textContent = message;
            notification.classList.add('show');
            setTimeout(() => {
                notification.classList.remove('show');
            }, 3000);
        }
    }

    saveSubscription(email) {
        const subscriptions = JSON.parse(localStorage.getItem('newsletter_subscriptions') || '[]');
        if (!subscriptions.includes(email)) {
            subscriptions.push(email);
            localStorage.setItem('newsletter_subscriptions', JSON.stringify(subscriptions));
        }
    }
}

/* ============================================
   Navigation & Scrolling
   ============================================ */

class Navigation {
    constructor() {
        this.navLinks = document.querySelectorAll('.nav-primary a');
        this.setupSmoothScroll();
        this.highlightActive();
        window.addEventListener('scroll', () => this.highlightActive());
    }

    setupSmoothScroll() {
        this.navLinks.forEach(link => {
            link.addEventListener('click', (e) => {
                const href = link.getAttribute('href');
                if (href.startsWith('#')) {
                    e.preventDefault();
                    const target = document.querySelector(href);
                    if (target) {
                        const headerHeight = document.querySelector('header').offsetHeight;
                        const targetPosition = target.offsetTop - headerHeight;
                        window.scrollTo({
                            top: targetPosition,
                            behavior: 'smooth'
                        });

                        // Update focus for accessibility
                        target.focus();
                    }
                }
            });
        });
    }

    highlightActive() {
        const sections = document.querySelectorAll('section[id]');
        let current = '';

        sections.forEach(section => {
            const sectionTop = section.offsetTop - 100;
            if (window.scrollY >= sectionTop) {
                current = section.getAttribute('id');
            }
        });

        this.navLinks.forEach(link => {
            link.classList.remove('active');
            if (link.getAttribute('href') === `#${current}`) {
                link.classList.add('active');
                link.setAttribute('aria-current', 'page');
            } else {
                link.removeAttribute('aria-current');
            }
        });
    }
}

/* ============================================
   Product Interactions
   ============================================ */

class ProductInteractions {
    constructor() {
        this.setupProductCards();
        this.setupEditorialCards();
    }

    setupProductCards() {
        document.querySelectorAll('.product-card').forEach(card => {
            card.addEventListener('mouseenter', () => this.elevateCard(card));
            card.addEventListener('mouseleave', () => this.normalizeCard(card));

            // Keyboard navigation
            card.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && e.target.closest('.btn-add-cart')) {
                    e.preventDefault();
                    e.target.closest('.btn-add-cart').click();
                }
            });
        });
    }

    setupEditorialCards() {
        document.querySelectorAll('.editorial-card').forEach(card => {
            const link = card.querySelector('.read-more');
            if (link) {
                card.style.cursor = 'pointer';
                card.addEventListener('click', (e) => {
                    if (!e.target.closest('a')) {
                        link.click();
                    }
                });

                // Keyboard support
                card.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        link.click();
                    }
                });
            }
        });
    }

    elevateCard(card) {
        card.style.transform = 'translateY(-8px)';
    }

    normalizeCard(card) {
        card.style.transform = 'translateY(0)';
    }
}

/* ============================================
